// This module is lazy-loaded on a gift click. Only generic artwork/font URLs
// are fetched; all recipient text and generated bytes stay in this browser.
import { PDFDocument, rgb } from 'pdf-lib';
import fontkit from '@pdf-lib/fontkit';
import { certificateDownloadFilename, CERTIFICATE_FONT } from './niceListCertificate.js';
import { fitSantaPictureName, santaPictureFrames } from './santaPictureLayout.js';
import { SIGNATURE_FONT, loadRecipientFont, recipientCanvasFont, recipientDisplayName } from './giftFonts.js';
import { studioLetterLayout as letterType, fitStudioLetterLines } from './studioLetterLayout.js';

export const LETTER_SERIF = '/certificates/nice-list/CertificateSerif.ttf';
export const LETTER_HEAD = '/images/santa-radio-letterhead.webp';
const features = { calt: false, liga: false, clig: false };

export function studioGiftFilename(kind, name) {
  const recipient = certificateDownloadFilename(name)
    .slice('Santa-Radio-Nice-List-Certificate-'.length, -4);
  return `Santa-Radio-${kind === 'letter' ? 'Letter' : 'Santa-Picture'}-${recipient}.${kind === 'letter' ? 'pdf' : 'png'}`;
}

async function bytes(url) {
  const response = await fetch(url, { credentials: 'omit', cache: 'no-cache' });
  if (!response.ok) throw new Error('Gift asset unavailable');
  return new Uint8Array(await response.arrayBuffer());
}

async function imageCanvas(url) {
  // Fetch explicitly so corrupt responses can be retried independently of the
  // browser's decoded preview-image cache.
  const data = await bytes(url);
  const objectUrl = URL.createObjectURL(new Blob([data]));
  const image = new Image();
  image.src = objectUrl;
  try { await image.decode(); } finally { URL.revokeObjectURL(objectUrl); }
  if (!image.naturalWidth || !image.naturalHeight) throw new Error('Gift artwork unavailable');
  const canvas = document.createElement('canvas');
  canvas.width = image.naturalWidth;
  canvas.height = image.naturalHeight;
  const context = canvas.getContext('2d');
  if (!context) throw new Error('Image export unavailable');
  context.drawImage(image, 0, 0);
  return canvas;
}

function canvasBlob(canvas) {
  return new Promise((resolve, reject) => canvas.toBlob(
    blob => blob ? resolve(blob) : reject(new Error('PNG export failed')), 'image/png'));
}

function checkCharacters(fontBytes, text) {
  const metrics = fontkit.create(fontBytes);
  if ([...text].some(character => !metrics.hasGlyphForCodePoint(character.codePointAt(0)))) {
    throw new Error('The gift font cannot write one of these characters');
  }
}

export async function exportStudioPicture(name, picture) {
  if (!santaPictureFrames[picture]) throw new Error('Unknown Santa artwork');
  const [canvas, script] = await Promise.all([imageCanvas(picture), bytes(CERTIFICATE_FONT)]);
  checkCharacters(script, name);
  await loadRecipientFont(script);
  const context = canvas.getContext('2d');
  const fit = fitSantaPictureName(context, name, picture);
  const frame = santaPictureFrames[picture];
  context.save();
  context.scale(canvas.width / 1536, canvas.height / 1024);
  context.font = recipientCanvasFont(fit.size);
  context.fillStyle = '#19392d';
  for (const line of fit.lines) {
    context.fillText(line.text, frame.x + line.x, frame.y + line.y);
  }
  context.restore();
  return canvasBlob(canvas);
}

// Wrap by glyph advance; split even an unusually long unbroken written name.
export function wrapLetterText(text, font, size, maxWidth) {
  const lines = [];
  let line = '';
  for (const word of text.split(/\s+/u)) {
    const candidate = line ? `${line} ${word}` : word;
    if (font.widthOfTextAtSize(candidate, size) <= maxWidth) { line = candidate; continue; }
    if (line) { lines.push(line); line = ''; }
    for (const character of word) {
      if (line && font.widthOfTextAtSize(line + character, size) > maxWidth) {
        lines.push(line); line = '';
      }
      line += character;
    }
  }
  if (line) lines.push(line);
  return lines;
}

export function layoutStudioLetter(letter, font) {
  const width = 595.2756, height = 841.8898;
  const maxWidth = width * (1 - 2 * letterType.inset);
  const size = width * letterType.body;
  const paragraphs = letter.paragraphs.map(text => wrapLetterText(text, font, size, maxWidth));
  const closing = letter.closing.map(text => wrapLetterText(text, font, size,
    width * (1 - 2 * letterType.closingInset)));
  const signatureSize = width * letterType.signature;
  const spacing = fitStudioLetterLines(
    [...paragraphs, ...closing].reduce((sum, lines) => sum + lines.length, 0),
    paragraphs.length + closing.length, letterType.bottom, letterType.pdfSignatureClearance);
  return { width, height, size, signatureSize, paragraphs, closing, ...spacing,
    x: width * letterType.inset, closingX: width * letterType.closingInset,
    top: height * (1 - letterType.top) };
}

export async function exportStudioLetter(letter) {
  // Direct callers use the same dual-renderer editorial decision as Review.
  if (!letter.browserLayout) {
    const { prepareStudioLetter } = await import('./prepareStudioLetter.js');
    letter = await prepareStudioLetter(letter);
  }
  const [serifBytes, scriptBytes, canvas] = await Promise.all([
    bytes(LETTER_SERIF), bytes(SIGNATURE_FONT), imageCanvas(LETTER_HEAD),
  ]);
  checkCharacters(serifBytes, [...letter.paragraphs, ...letter.closing].join(' '));
  const pdf = await PDFDocument.create();
  pdf.registerFontkit(fontkit);
  const serif = await pdf.embedFont(serifBytes, { subset: false, features: { ...features } });
  const script = await pdf.embedFont(scriptBytes, { subset: false, features: { ...features } });
  const layout = layoutStudioLetter(letter, serif);
  const page = pdf.addPage([layout.width, layout.height]);
  const background = await pdf.embedPng(await (await canvasBlob(canvas)).arrayBuffer());
  page.drawImage(background, { x: 0, y: 0, width: layout.width, height: layout.height });
  let y = layout.top - layout.size;
  const drawParagraphs = (paragraphs, x = layout.x) => {
    for (const lines of paragraphs) {
      for (const text of lines) {
        page.drawText(text, { x, y, size: layout.size, font: serif, color: rgb(38 / 255, 62 / 255, 50 / 255) });
        y -= layout.size * layout.leading;
      }
      y -= layout.size * layout.paragraphGap;
    }
  };
  drawParagraphs(layout.paragraphs);
  y -= layout.signatureSize * .8;
  page.drawText('Santa Claus', { x: layout.x, y, size: layout.signatureSize, font: script,
    color: rgb(128 / 255, 96 / 255, 35 / 255) });
  y -= layout.signatureSize * .7 + letterType.pdfSignatureClearance;
  drawParagraphs(layout.closing, layout.closingX);
  // No recipient metadata, server storage, preview overlays or DOM screenshots.
  return new Blob([await pdf.save()], { type: 'application/pdf' });
}
